import{G as e,W as t,n,rt as r}from"./chunks/framework.CMPLvzN_.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"常识/科技/天文.md","filePath":"常识/科技/天文.md"}`),a={name:`常识/科技/天文.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h2 id="神舟飞船" tabindex="-1">神舟飞船 <a class="header-anchor" href="#神舟飞船" aria-label="Permalink to “神舟飞船”">​</a></h2><p>长征二号F运载火箭执行了从神舟一号至今的所有载人飞船和目标飞行器发射任务</p><p>神舟十二号是<strong>首次进行空间站与地面实时视频通讯</strong>。</p><p>神舟十四号是<strong>中国航天员首次在轨进入科学实验舱</strong>。</p><p>神舟十五号是<strong>载人航天首次实现6名航天员同时在轨飞行的“新突破”</strong>。</p><p>神舟十七号是<strong>首次进行空间站舱外试验性维修作业</strong>。</p><h2 id="嫦娥飞船" tabindex="-1">嫦娥飞船 <a class="header-anchor" href="#嫦娥飞船" aria-label="Permalink to “嫦娥飞船”">​</a></h2><p><strong>嫦娥四号</strong>是人类第一个着陆月球背面的探测器</p><h2 id="火星探测器" tabindex="-1">火星探测器 <a class="header-anchor" href="#火星探测器" aria-label="Permalink to “火星探测器”">​</a></h2><p><strong>天问一号</strong>是中国首个火星探测器，中国成为了第二个探测器成功着陆火星的国家。</p><p><strong>祝融号</strong>是中国首个火星车，成为了中国首个在火星表面行驶的探测器。是由天问一号搭载</p><h2 id="空间站" tabindex="-1">空间站 <a class="header-anchor" href="#空间站" aria-label="Permalink to “空间站”">​</a></h2><p>中国是第三个能够独立研究和制造空间站的国家。（前二为前苏联和美国）</p><p>我国空间站主要由核心舱、实验舱、载人飞船和货运飞船等模块组成。 按照时间顺序，空间站模块依次为：</p><ol><li>天和核心舱</li><li>问天实验舱</li><li>梦天实验舱</li><li>天舟五号货运飞船</li><li>神舟十五号载人飞船</li><li>天舟七号货运飞船</li></ol><h2 id="北斗卫星" tabindex="-1">北斗卫星 <a class="header-anchor" href="#北斗卫星" aria-label="Permalink to “北斗卫星”">​</a></h2><p>中国北斗卫星导航系统（BDS）是中国自行研制的全球卫星导航系统。是世界上第三个成熟的卫星导航系统（前二为美国和俄罗斯）</p><h2 id="暗物质探测卫星" tabindex="-1">暗物质探测卫星 <a class="header-anchor" href="#暗物质探测卫星" aria-label="Permalink to “暗物质探测卫星”">​</a></h2><p>是<strong>悟空号</strong></p>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};